function ratingLevel(value){return value===null||value===undefined?null:Math.max(1,Math.min(5,Math.round(value)))}
function ratingColor(value){return RATING_COLORS[ratingLevel(value)]||'#a6afb8'}
function cleanGenre(value){return String(value).normalize('NFC').trim().replace(/\s+/g,' ').slice(0,50)}
function canonicalGenres(values){const result=[],seen=new Set();for(const value of values){let label=cleanGenre(value);label=DEFAULT_GENRES.find(g=>g.toLocaleLowerCase()===label.toLocaleLowerCase())||label;const key=label.toLocaleLowerCase();if(label&&!seen.has(key)){seen.add(key);result.push(label)}}return result}

