function persist(next=films){try{localStorage.setItem(KEY,JSON.stringify(next));films=next;storageError=false;updateStorage();return true}catch{storageError=true;updateStorage();toast('Không lưu được: bộ nhớ trình duyệt đã đầy. Hãy xuất dữ liệu trước.');return false}}
