const COLLECTION_PREFS='afterglow.collection.v1';let groupBy='none',filterMonth='',filterYear='';try{const pref=JSON.parse(localStorage.getItem(COLLECTION_PREFS)||'{}');if(['none','month','rank'].includes(pref.groupBy))groupBy=pref.groupBy}catch{}
function collectionRecords(data,filters={}){const month=String(filters.month||''),year=String(filters.year||''),query=String(filters.search||'').trim().toLocaleLowerCase();const records=[];for(const film of data){if(filters.genre&&!film.genres.includes(filters.genre)||filters.unrated&&score(film)!==null||!`${film.title} ${film.originalTitle}`.toLocaleLowerCase().includes(query))continue;const dates=film.watches.map(w=>w.date).filter(validDate).filter(d=>(!month||Number(d.slice(5,7))===Number(month))&&(!year||d.slice(0,4)===year)).sort().reverse();if((month||year)&&!dates.length)continue;records.push({film,date:dates[0]||''})}const sorting=filters.sort||'watched';records.sort(sorting==='rating'?(a,b)=>(score(b.film)??-1)-(score(a.film)??-1)||a.film.title.localeCompare(b.film.title,'vi'):sorting==='title'?(a,b)=>a.film.title.localeCompare(b.film.title,'vi'):sorting==='year'?(a,b)=>(b.film.year||0)-(a.film.year||0)||a.film.title.localeCompare(b.film.title,'vi'):(a,b)=>b.date.localeCompare(a.date)||String(b.film.updatedAt||'').localeCompare(String(a.film.updatedAt||'')));return records}
function collectionGroups(records,mode){if(mode==='none')return[{key:'all',label:'',records}];const map=new Map();for(const record of records){const key=mode==='month'?(record.date.slice(0,7)||'undated'):String(ratingLevel(score(record.film))??'unrated');if(!map.has(key))map.set(key,[]);map.get(key).push(record)}const keys=[...map.keys()].sort(mode==='month'?(a,b)=>a==='undated'?1:b==='undated'?-1:b.localeCompare(a):(a,b)=>a==='unrated'?1:b==='unrated'?-1:Number(b)-Number(a));return keys.map(key=>({key,label:mode==='month'?(key==='undated'?'Chưa ghi ngày xem':`Tháng ${Number(key.slice(5,7))} · ${key.slice(0,4)}`):(RATING_LABELS[key]||'Chưa chấm đủ'),color:mode==='rank'?ratingColor(key==='unrated'?null:Number(key)):null,records:[...map.get(key)].sort((a,b)=>(score(b.film)??-1)-(score(a.film)??-1)||b.date.localeCompare(a.date)||a.film.title.localeCompare(b.film.title,'vi'))}))}
function card(f,watchDate=latest(f).date){return `<article class="film-card"><button class="poster-button" data-open="${f.id}" aria-label="Xem ${esc(f.title)}">${imageHtml(f)}</button><div class="card-heading"><button class="film-title" data-open="${f.id}">${esc(f.title)}</button><span class="card-score" style="color:${ratingColor(score(f))}" aria-label="${scoreText(f)} trên 5">${scoreText(f)}<span> / 5</span></span></div><div class="card-meta">${f.year||'—'} ${f.genres.length?'· '+esc(f.genres.slice(0,2).join(' / ')):''}</div><div class="card-watch"><span>${watchDate?dateText(watchDate):'Chưa ghi ngày xem'}</span>${f.demo?'<span class="demo-label">MẪU</span>':''}</div></article>`}
